"""Generates flashcards/month-04.csv (Anki import: Front, Back, Tags) for Days 92-120. Edit the list, then re-run.
Every number on a card comes from a run of the course scripts on this box (CPU only): Week 17 logs in code/week-17/out/
and the capstone log code/week-18/out/day120_capstone.log. Day 91 cards are in month-03.csv."""
import csv, os
C = [
(92,"Self-attention in one line?","Each position's output is a weighted average of value vectors; weights = softmax of its query's dot products with all keys."),
(92,"Why multiple heads?","Each head attends with its own projections, so different heads can track different relations; outputs are concatenated and projected."),
(92,"Padding mask vs causal mask?","Padding mask hides pad tokens in any model; causal mask hides future positions in a decoder."),
(92,"Shape of attention scores for B sequences, H heads, length T?","[B, H, T, T]."),
(92,"Cost of attention in sequence length T?","O(T²) time and memory for the score matrix (O(T² d) compute)."),
(93,"Sinusoidal positional encoding?","Fixed sin/cos of position at geometrically spaced frequencies, added to the token embeddings."),
(93,"Learned vs sinusoidal positions?","Learned: a trainable vector per position, limited to the trained length; sinusoidal: fixed, defined for any position."),
(93,"What does RoPE rotate?","Pairs of dimensions of q and k, by angles proportional to the position; v is not rotated."),
(93,"Why does RoPE encode relative position?","The dot product of two rotated vectors depends only on the difference of their rotation angles, i.e. positions."),
(94,"Pre-norm block?","x = x + Attn(Norm(x)); x = x + MLP(Norm(x)). More stable to train deep than post-norm."),
(94,"Role of residual connections?","Give gradients a direct path and let each sub-layer learn a correction to the stream."),
(94,"Typical transformer MLP?","Expand to ~4× width, nonlinearity (GELU, or SwiGLU gating), project back."),
(94,"RMSNorm vs LayerNorm?","RMSNorm only rescales by the root mean square (no mean subtraction, no bias); cheaper, used in Llama-style models."),
(94,"SwiGLU?","silu(x W_g) ⊙ (x W_u), then W_d: a gated MLP used in Llama/SmolLM2."),
(95,"Training objective of a GPT?","Next-token prediction: cross-entropy between predicted distribution at position t and the token at t+1."),
(95,"Weight tying?","Use the token embedding matrix as the output projection (lm_head); saves parameters."),
(95,"Temperature in sampling?","Divide logits by T before softmax: T<1 sharper, T>1 flatter; T→0 is greedy."),
(95,"Top-k vs top-p sampling?","Top-k keeps the k most likely tokens; top-p keeps the smallest set whose probability sums to p."),
(96,"BPE training loop?","Start from characters/bytes; repeatedly merge the most frequent adjacent pair into a new token until the vocabulary size is reached."),
(96,"Why byte-level BPE?","Any string can be encoded (no unknown tokens), since the base alphabet is all 256 bytes."),
(96,"Effect of a bigger vocabulary?","Shorter sequences but a larger embedding/output matrix and rarer tokens."),
(96,"Why can tokenisation hurt arithmetic?","Numbers split into irregular chunks, so digits are not aligned across examples."),
(97,"Causal LM vs masked LM?","Causal predicts the next token left-to-right (GPT); masked predicts hidden tokens from both sides (BERT)."),
(97,"Perplexity?","exp(mean cross-entropy in nats per token); lower is better."),
(97,"Scaling laws in one sentence?","Loss falls as a smooth power law in parameters, data and compute; compute-optimal training balances model size and tokens."),
(97,"Chinchilla takeaway?","For a fixed compute budget, many earlier models were too large for their data; train smaller models on more tokens."),
(98,"Why compare a model with a unigram baseline?","It shows how much the model learns beyond token frequencies."),
(98,"Why report validation, not training, loss for a tiny GPT?","Training loss falls even when the model memorises; validation shows generalisation."),
(99,"AutoTokenizer / AutoModelForCausalLM?","Load the matching tokenizer and model class from a Hub id or local cache using its config."),
(99,"What does HF_HUB_OFFLINE=1 do?","Uses only the local cache; no network calls to the Hub."),
(99,"Why set pad_token for causal LMs?","Many have no pad token; batching needs one (often set to eos) plus an attention mask."),
(99,"datasets.map(batched=True)?","Applies a function to batches of examples, e.g. tokenisation, with caching."),
(100,"Full fine-tuning?","Update all weights of a pretrained model on task data, usually with a small learning rate."),
(100,"Catastrophic forgetting?","Fine-tuning on narrow data degrades the model's earlier abilities; measure on held-out general text."),
(100,"Why a small LR when fine-tuning?","The pretrained weights are already good; large steps destroy them."),
(101,"LoRA update?","W' = W + (α/r)·B A with W frozen; B is d×r, A is r×k, B initialised to zero."),
(101,"Parameters added by rank-r LoRA on a d×k matrix?","r(d + k)."),
(101,"Why initialise LoRA B to zero?","The adapted model starts exactly equal to the base model."),
(101,"Can LoRA be merged for inference?","Yes: add (α/r)BA into W; no extra latency."),
(102,"Which modules does LoRA usually target?","Attention projections (q, k, v, o) and often the MLP projections; more targets = more capacity."),
(102,"QLoRA idea?","Keep the frozen base model in 4-bit (NF4) and train LoRA adapters in higher precision on top."),
(102,"Effect of LoRA rank r?","Higher r = more capacity and parameters; small r often suffices for narrow tasks."),
(103,"What is a chat template?","The model-specific way to format system/user/assistant turns with special tokens, applied by tokenizer.apply_chat_template."),
(103,"Why mask user tokens in the SFT loss?","The model should learn to produce responses, not to predict prompts."),
(103,"add_generation_prompt=True?","Appends the assistant-turn header so the model starts writing the reply."),
(103,"SmolLM2-Instruct end-of-turn token?","<|im_end|>; generation should stop on it as well as eos."),
(104,"Why multiple eval types for an LLM?","Perplexity, exact match, held-out general text and human/LLM judgement measure different things."),
(104,"Exact match pitfall?","Formatting differences ('2,442,817' vs '2442817') count as wrong unless you normalise."),
(105,"Full fine-tune vs LoRA trade-off?","LoRA trains far fewer parameters and forgets less; full fine-tuning can fit the task more closely."),
(106,"Bradley-Terry model?","P(a ≻ b) = σ(r(a) − r(b))."),
(106,"KL-regularised RLHF objective?","maximise E[r(x,y)] − β·KL(π ‖ π_ref)."),
(106,"Optimal policy of the KL-regularised objective?","π*(y|x) ∝ π_ref(y|x)·exp(r(x,y)/β)."),
(106,"Why the KL term?","Keeps the policy close to the reference so it doesn't exploit reward-model errors or lose fluency."),
(107,"Reward model architecture?","A language model with a scalar head on the last token, trained with the Bradley-Terry loss on preference pairs."),
(107,"Reward shortcut example?","The reward model learns length or a surface feature instead of quality."),
(107,"How to detect reward shortcuts?","Test on pairs where the shortcut feature is controlled or reversed."),
(108,"DPO loss?","−log σ(β[(log π(y_w)−log π_ref(y_w)) − (log π(y_l)−log π_ref(y_l))])."),
(108,"DPO loss at initialisation (π = π_ref)?","log 2 ≈ 0.693, since the margin is 0."),
(108,"What does DPO avoid compared with PPO RLHF?","Training a separate reward model and sampling/RL; it optimises the preference data directly."),
(108,"DPO's implicit reward?","β·log(π(y|x)/π_ref(y|x))."),
(109,"Effect of β in DPO?","Larger β keeps the policy closer to the reference; smaller β allows bigger moves."),
(109,"Known DPO failure?","It can lower the log-probability of both chosen and rejected answers; adding an NLL term on chosen answers helps."),
(110,"Data contamination?","Test items (or near copies) appearing in training data, inflating scores."),
(110,"LLM-judge biases?","Position, length and self-preference; swap order and control length."),
(110,"Why bootstrap confidence intervals for small eval sets?","With few items one question changes the score a lot; CIs show the uncertainty."),
(111,"Best-of-n?","Sample n answers and pick the best by a reward model or verifier."),
(111,"Reward hacking in best-of-n?","Larger n finds answers that score high on an imperfect reward but are not better."),
(111,"Oracle verifier?","A verifier with access to the true answer; gives an upper bound for best-of-n."),
(112,"SFT vs DPO vs DPO+NLL?","SFT imitates chosen answers; DPO contrasts chosen vs rejected; DPO+NLL adds an imitation term to keep chosen likelihood up."),
(113,"Mean pooling?","Average the token embeddings weighted by the attention mask, then L2-normalise."),
(113,"MiniLM-L6 embedding dimension?","384."),
(113,"Best chunking on Day 113 by recall@5?","By section: recall@5 0.71 (word windows 0.62-0.64)."),
(113,"int8 vs fp32 index on Day 113?","0.40 MB vs 1.59 MB; recall@5 0.62 vs 0.64."),
(113,"Recall@k and MRR?","Recall@k: relevant item in top k? MRR: mean of 1/rank of the first relevant item."),
(113,"Why chunk documents?","Embedding models have length limits (256 tokens used here) and one vector cannot summarise many topics."),
(114,"BM25 ingredients?","IDF of query terms, saturating term frequency (k1) and length normalisation (b)."),
(114,"Reciprocal rank fusion?","score = Σ 1/(k + rank) over retrievers, k ≈ 60; ranks only, no calibration."),
(114,"Bi-encoder vs cross-encoder?","Bi-encoder embeds query and doc separately (fast, precomputed); cross-encoder reads them together (accurate, slow)."),
(114,"Day 114 recall@5: dense / BM25 / hybrid / dense+rerank?","0.64 / 0.67 / 0.76 / 0.81."),
(114,"Cross-encoder rerank cost on Day 114?","About 200 ms per query for 20 candidates on CPU."),
(115,"Context recall vs answer accuracy?","Context recall: answer in retrieved text; accuracy: answer in the output. Their gap measures generation errors."),
(115,"Day 115 RAG numbers?","Context recall@3 0.92; accuracy closed-book 0.00, RAG 0.25."),
(115,"Why closed-book and oracle baselines?","Closed-book shows what the model knows; oracle shows the generator's ceiling with perfect retrieval."),
(116,"Symmetric quantisation?","s = max|w|/(2^(b−1)−1); q = round(w/s) clamped; ŵ = s·q."),
(116,"Per-tensor vs per-channel vs group-wise?","One scale per matrix / per output row / per g consecutive weights."),
(116,"SmolLM2-135M ppl: fp32 vs int8 per-channel (Day 116)?","26.29 vs 26.50."),
(116,"int4 per-tensor ppl on Day 116?","1,561,367.93: outliers set a huge scale and most weights round to zero."),
(116,"int4 group-64 / group-32 ppl on Day 116?","36.89 / 33.27 (fp32 26.29)."),
(116,"Why must group size divide the row length?","Each group needs whole rows split evenly; SmolLM2's 576-wide rows allow 64 or 32, not 128."),
(117,"GPTQ idea?","Quantise columns one at a time and update the remaining columns to compensate, using the inverse Hessian of XᵀX."),
(117,"AWQ idea?","Scale up weight channels that meet large activations (s = mean|x|^α) before quantising; fold 1/s into the input."),
(117,"Day 117 int4 per-channel ppl: RTN / AWQ / GPTQ?","64.84 / 44.04 / 44.31."),
(117,"Why might GPTQ's lower calibration error not lower perplexity?","It can overfit the small calibration set (2,048 tokens here)."),
(117,"Day 117 Rust int8 matmul vs torch fp32 at batch 1?","145.2 µs (8 threads) vs 15.9 µs: slower, but 4× less weight memory."),
(117,"Why run each kernel benchmark in its own process?","Rayon's spinning threads competed with torch's thread pool and corrupted the timings."),
(118,"Prefill vs decode?","Prefill processes the prompt in parallel (compute-bound); decode adds one token per step (memory-bound)."),
(118,"KV cache memory?","2 × layers × KV heads × head dim × tokens × bytes per value."),
(118,"Day 118 decode speed: no cache vs our KV cache?","27.3 vs 67.8 tok/s for 64 tokens, identical output."),
(118,"Batching on Day 118 (total tok/s at batch 1/4/16)?","63.6 / 186.3 / 559.8; per-sequence speed fell to 35.0 at batch 16."),
(118,"When is speculative decoding slower?","When acceptance is low; Day 118's early-exit draft had 0.03-0.06 acceptance and was slower."),
(118,"PagedAttention?","vLLM stores the KV cache in fixed-size blocks to avoid fragmentation and share prefixes."),
(118,"Why wasn't llama.cpp built in Week 17?","The box has gcc but no g++, cmake or make."),
(119,"Day 119 int8 vs fp32 generator?","Same accuracy 0.25, ppl 32.11 vs 32.05, but only 9 of 12 identical answers."),
(119,"Why no speed-up from simulated quantisation?","Weights are dequantised to fp32 for compute; real kernels are needed."),
(120,"Capstone failure categories (int8)?","3 correct, 1 retrieval miss, 8 generation errors (answer was in the context)."),
(120,"Capstone retrieval on 58 held-out questions?","recall@1 0.48, recall@5 0.79, 214 ms/query."),
(120,"Capstone latency breakdown per question?","About 0.2 s retrieval, 0.3 s prefill (816-token prompt), decode at about 60 tok/s."),
(120,"How was the from-scratch decoder validated in the capstone?","Its answer matched Hugging Face generate exactly on the int8 model (Q1)."),
(120,"Main conclusion of the capstone?","The 135M generator, not retrieval, limits quality; with only 12 questions this is indicative, not conclusive."),
]
out = os.path.join(os.path.dirname(os.path.abspath(__file__)), "month-04.csv")
with open(out, "w", newline="", encoding="utf-8") as f:
    w = csv.writer(f)
    for d, q, a in C: w.writerow([q, a, f"m4 d{d}"])
print(f"wrote {len(C)} cards to {out}")
